window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-94502c02aae6ff0a"]={"versions": [{"id": "FIG-94502c02aae6ff0a", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Schritts „Compute CRC“ innerhalb des AUTOSAR E2E Profile 4m (End-to-End-Kommunikationsschutz). Es modelliert die zweistufige Prüfsummenberechnung über serialisierte Nutzdaten und Header-Elemente unter Aussparung des CRC-Feldes selbst.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert den gemeinsamen Algorithmus für die drei E2E-Funktionen:</p>\n<ul class=\"fig-list\"><li><code>E2E_P04mProtect()</code>\n</li><li><code>E2E_P04mCheck()</code>\n</li><li><code>E2E_P04mForward()</code>\n</li></ul>\n<p class=\"fig-p\">Verwendete Schnittstellen und Entitäten:</p>\n<ul class=\"fig-list\"><li>Funktion <code>Crc_CalculateCRC32P4(Crc_DataPtr, Crc_Length, Crc_StartValue32, Crc_IsFirstCall)</code> aus der AUTOSAR CRC-Bibliothek.\n</li><li>Variablen und Parameter: <code>ComputedCRC</code> (uint32), Datenpuffer-Referenz <code>&amp;Data[0]</code> bzw. <code>&amp;Data[offset+12]</code>, Konfigurationswerte <code>Offset</code> (Byte-Offset des E2E-Headers) und <code>Length</code> (Gesamtlänge der geschützten Daten).\n</li><li>Konstanten: Startwert <code>0xFFFFFFFF</code> (dargestellt als <code>0xFF&#x27;FF&#x27;FF&#x27;FF</code>), boolesche Literale <code>TRUE</code> und <code>FALSE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beginnt an einem Initialknoten:</p>\n<ol class=\"fig-list\"><li>Erster Aufruf von <code>Crc_CalculateCRC32P4</code>: Berechnung der Prüfsumme über den Datenbereich vor dem CRC-Feld. Übergabeparameter sind <code>Crc_DataPtr: &amp;Data[0]</code>, <code>Crc_Length: Offset+8</code>, <code>Crc_StartValue32: 0xFF&#x27;FF&#x27;FF&#x27;FF</code> und <code>Crc_IsFirstCall: TRUE</code>. Das Ergebnis wird in <code>uint32 ComputedCRC</code> gespeichert. (Länge <code>Offset+8</code> entspricht den Nutzdaten vor dem E2E-Header plus den 8 Header-Bytes vor der 4-Byte-CRC).\n</li><li>Verzweigungsknoten (Decision): Auswertung der Guard-Bedingung <code>Offset + 12 &lt; Length</code>.\n</li><li>Zweig <code>[true]</code>: Wenn nach dem 4 Byte großen CRC-Feld (Offset + 8 bis Offset + 11) weitere Daten folgen, wird <code>Crc_CalculateCRC32P4</code> erneut aufgerufen mit <code>Crc_DataPtr: &amp;Data[offset+12]</code>, <code>Crc_Length: Length-Offset-12</code>, <code>Crc_StartValue32: ComputedCRC</code> und <code>Crc_IsFirstCall: FALSE</code>. Der berechnete Wert überschreibt <code>ComputedCRC</code>.\n</li><li>Zweig <code>[false]</code>: Endet der Datenblock direkt mit dem CRC-Feld, wird dieser zweite Aufruf übersprungen.\n</li><li>Beide Pfade münden in einen Zusammenführungsknoten (Merge), der unmittelbar in den Endknoten der Aktivität führt. Am Ausgang steht die vollständige <code>ComputedCRC</code> für die weiteren Schritte zur Verfügung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Ablauf zur Berechnung der 32-Bit-CRC (Profile 4m, Generatorpolynom 0xF4ACFB13) gemäß Anforderung <code>RS_E2E_08539</code>. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die Aufteilung in maximal zwei CRC-Berechnungsschritte spart das separate Ausnullen des CRC-Feldes im Sendepuffer und ermöglicht In-Place- bzw. Streaming-Verarbeitung.\n</li><li>Der Parameter <code>offset</code> gibt die Anzahl der Bytes vor dem E2E-Header an, <code>8</code> die Anzahl der Header-Bytes vor dem 4-Byte-CRC-Feld.\n</li><li>Das CRC-Feld umfasst exakt 4 Bytes (<code>Offset + 8</code> bis <code>Offset + 11</code>), weshalb der zweite Datenblock bei <code>Offset + 12</code> beginnt und eine Länge von <code>Length - Offset - 12</code> aufweist.\n</li><li>Ist <code>Offset + 12 == Length</code>, darf kein zweiter CRC-Aufruf mit Länge 0 erfolgen.\n</li><li>Bei <code>Crc_IsFirstCall: FALSE</code> muss zwingend der Zwischenwert <code>ComputedCRC</code> als <code>Crc_StartValue32</code> übergeben werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-59e58de2a30de845", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Schritts „Compute CRC“ innerhalb des AUTOSAR E2E Profile 4m (End-to-End-Kommunikationsschutz). Es modelliert die zweistufige Prüfsummenberechnung über serialisierte Nutzdaten und Header-Elemente unter Aussparung des CRC-Feldes selbst.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert den gemeinsamen Algorithmus für die drei E2E-Funktionen:</p>\n<ul class=\"fig-list\"><li><code>E2E_P04mProtect()</code>\n</li><li><code>E2E_P04mCheck()</code>\n</li><li><code>E2E_P04mForward()</code>\n</li></ul>\n<p class=\"fig-p\">Verwendete Schnittstellen und Entitäten:</p>\n<ul class=\"fig-list\"><li>Funktion <code>Crc_CalculateCRC32P4(Crc_DataPtr, Crc_Length, Crc_StartValue32, Crc_IsFirstCall)</code> aus der AUTOSAR CRC-Bibliothek.\n</li><li>Variablen und Parameter: <code>ComputedCRC</code> (uint32), Datenpuffer-Referenz <code>&amp;Data[0]</code> bzw. <code>&amp;Data[offset+12]</code>, Konfigurationswerte <code>Offset</code> (Byte-Offset des E2E-Headers) und <code>Length</code> (Gesamtlänge der geschützten Daten).\n</li><li>Konstanten: Startwert <code>0xFFFFFFFF</code> (dargestellt als <code>0xFF&#x27;FF&#x27;FF&#x27;FF</code>), boolesche Literale <code>TRUE</code> und <code>FALSE</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf beginnt an einem Initialknoten:</p>\n<ol class=\"fig-list\"><li>Erster Aufruf von <code>Crc_CalculateCRC32P4</code>: Berechnung der Prüfsumme über den Datenbereich vor dem CRC-Feld. Übergabeparameter sind <code>Crc_DataPtr: &amp;Data[0]</code>, <code>Crc_Length: Offset+8</code>, <code>Crc_StartValue32: 0xFF&#x27;FF&#x27;FF&#x27;FF</code> und <code>Crc_IsFirstCall: TRUE</code>. Das Ergebnis wird in <code>uint32 ComputedCRC</code> gespeichert. (Länge <code>Offset+8</code> entspricht den Nutzdaten vor dem E2E-Header plus den 8 Header-Bytes vor der 4-Byte-CRC).\n</li><li>Verzweigungsknoten (Decision): Auswertung der Guard-Bedingung <code>Offset + 12 &lt; Length</code>.\n</li><li>Zweig <code>[true]</code>: Wenn nach dem 4 Byte großen CRC-Feld (Offset + 8 bis Offset + 11) weitere Daten folgen, wird <code>Crc_CalculateCRC32P4</code> erneut aufgerufen mit <code>Crc_DataPtr: &amp;Data[offset+12]</code>, <code>Crc_Length: Length-Offset-12</code>, <code>Crc_StartValue32: ComputedCRC</code> und <code>Crc_IsFirstCall: FALSE</code>. Der berechnete Wert überschreibt <code>ComputedCRC</code>.\n</li><li>Zweig <code>[false]</code>: Endet der Datenblock direkt mit dem CRC-Feld, wird dieser zweite Aufruf übersprungen.\n</li><li>Beide Pfade münden in einen Zusammenführungsknoten (Merge), der unmittelbar in den Endknoten der Aktivität führt. Am Ausgang steht die vollständige <code>ComputedCRC</code> für die weiteren Schritte zur Verfügung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Ablauf zur Berechnung der 32-Bit-CRC (Profile 4m, Generatorpolynom 0xF4ACFB13) gemäß Anforderung <code>RS_E2E_08539</code>. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die Aufteilung in maximal zwei CRC-Berechnungsschritte spart das separate Ausnullen des CRC-Feldes im Sendepuffer und ermöglicht In-Place- bzw. Streaming-Verarbeitung.\n</li><li>Der Parameter <code>offset</code> gibt die Anzahl der Bytes vor dem E2E-Header an, <code>8</code> die Anzahl der Header-Bytes vor dem 4-Byte-CRC-Feld.\n</li><li>Das CRC-Feld umfasst exakt 4 Bytes (<code>Offset + 8</code> bis <code>Offset + 11</code>), weshalb der zweite Datenblock bei <code>Offset + 12</code> beginnt und eine Länge von <code>Length - Offset - 12</code> aufweist.\n</li><li>Ist <code>Offset + 12 == Length</code>, darf kein zweiter CRC-Aufruf mit Länge 0 erfolgen.\n</li><li>Bei <code>Crc_IsFirstCall: FALSE</code> muss zwingend der Zwischenwert <code>ComputedCRC</code> als <code>Crc_StartValue32</code> übergeben werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-94502c02aae6ff0a", "to": "FIG-59e58de2a30de845", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
